// Adaptive sampling decision using deterministic hashing
function shouldSample(tenantId, eventId, quotaMap) {
  const quota = quotaMap[tenantId];
  if (!quota || quota.allowBurst) return true;

  const hash = hashFunction(tenantId + eventId) % 100;
  return hash < quota.sampleRate;
